class Command(BaseCommand):
    help = 'Seeds the database with Game of Thrones characters, profile pictures, and endorsements'

    def handle(self, *args, **options):
        self.stdout.write('Seeding Game of Thrones characters...')

        with transaction.atomic():
            Endorsement.objects.all().delete()
            ProfilePicture.objects.all().delete()
            User.objects.all().delete()

            users = {}
            for data in CHARACTERS:
                user = User.objects.create_user(
                    username=data['username'],
                    email=data['email'],
                    password=None,  # Seed profiles cannot sign in until a password is set.
                    first_name=data['first_name'],
                    last_name=data['last_name'],
                    gender=data['gender'],
                    bio=data['bio'],
                    is_superuser=data.get('is_superuser', False),
                    is_staff=data.get('is_staff', False),
                    can_try_to_kill=data.get('can_try_to_kill', False),
                    is_unkillable=data.get('is_unkillable', False),
                )
                if data['username'] in IMAGE_DATA:
                    image_bytes = base64.b64decode(''.join(IMAGE_DATA[data['username']]))
                    ProfilePicture.objects.create(
                        user=user,
                        image_data=image_bytes,
                        is_primary=True,
                        order=0,
                    )
                for i, b64_chunks in enumerate(ADDITIONAL_IMAGES.get(data['username'], [])):
                    image_bytes = base64.b64decode(''.join(b64_chunks) if isinstance(b64_chunks, tuple) else b64_chunks)
                    ProfilePicture.objects.create(
                        user=user,
                        image_data=image_bytes,
                        is_primary=False,
                        order=i + 1,
                    )
                users[data['username']] = user
                self.stdout.write(f'  Created {user.get_full_name() or user.username}')

            self.stdout.write('Seeding endorsements...')
            for row in ENDORSEMENTS:
                username_a, username_b, endorsement_type, stmt_a, stmt_b = row
                if username_a not in users or username_b not in users:
                    self.stdout.write(self.style.WARNING(f'  Skipping {username_a} <-> {username_b} (missing user)'))
                    continue

                both_approved = stmt_a is not None and stmt_b is not None
                Endorsement.objects.create(
                    first_user=users[username_a],
                    second_user=users[username_b],
                    endorsement_type=endorsement_type,
                    first_user_approved=both_approved,
                    second_user_approved=both_approved,
                    first_user_statement=stmt_a or '',
                    second_user_statement=stmt_b or '',
                    first_user_did_approve_text=both_approved,
                    second_user_did_approve_text=both_approved,
                    is_joining_endorsement=both_approved,
                )
                label = 'Romantic' if endorsement_type == 'romantic' else 'Platonic'
                self.stdout.write(f'  {label}: {username_a} <-> {username_b}')

        self.stdout.write(self.style.SUCCESS(
            f'\nDone. {len(users)} characters, {Endorsement.objects.count()} endorsements.'
        ))
